#if OPENNET_TESTING
using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using NetworkHub.App;
using NetworkHub.Dns;
namespace NetworkHub.Desktop;
internal static class TestsSecondaryIntegration
{
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Click(Window window,string name)=>((Button)window.FindName(name)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static Window Manager(Shell shell)=>shell.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("ModulesDefaults")!=null);
    internal static void Headless(Action<string,Action> test)
    {
        test("Integrated defaults change only module order visibility and startup choices",()=>{var original=new UserSettings{Language="ru",Theme="light",Backdrop="acrylic",StartupZapret=false,StartupTg=false,DnsProfileId="magic",DnsProfileName="MagicDNS",DnsAdapterId="adapter",Strategy="general (ALT2).bat",PendingStrategy="pending",StartupInstallationId="registration",StartWithWindows=true,AutoStartTools=true};original.Workspace.Primary="dns";original.Workspace.ManualHeight=true;original.Workspace.Height=544;original.Workspace.Order=new[]{"dns","tg","zapret"};original.Workspace.Visible=new[]{"dns"};string before=JsonSerializer.Serialize(original);var plan=WorkspaceDefaults.Plan(original);Check(before==JsonSerializer.Serialize(original),"Planning mutated preferences");Check(plan.Workspace.Order.SequenceEqual(WorkspaceSettings.Modules)&&plan.Workspace.Visible.SequenceEqual(WorkspaceSettings.Modules)&&plan.StartupZapret==true&&plan.StartupTg==true,"Defaults missing");plan.Workspace.Order=original.Workspace.Order;plan.Workspace.Visible=original.Workspace.Visible;plan.StartupZapret=original.StartupZapret;plan.StartupTg=original.StartupTg;Check(JsonSerializer.Serialize(plan)==before,"Reset changed unrelated preferences");});
        test("Integrated default plan preserves migrated stable and prior alpha preferences",()=>{foreach(string json in new[]{"{\"Language\":\"ru\",\"Theme\":\"light\",\"Backdrop\":\"solid\",\"Strategy\":\"general.bat\",\"AutoStartTools\":true}","{\"Language\":\"en\",\"DnsProfileId\":\"saved:owned\",\"DnsProfileName\":\"Custom\",\"Workspace\":{\"Primary\":\"dns\",\"ManualHeight\":true,\"Height\":601}}"}){var old=JsonSerializer.Deserialize<UserSettings>(json)!;var copy=WorkspaceDefaults.Plan(old);Check(copy.Language==old.Language&&copy.Theme==old.Theme&&copy.Backdrop==old.Backdrop&&copy.Strategy==old.Strategy&&copy.DnsProfileId==old.DnsProfileId&&copy.Workspace.Primary==old.Workspace.Primary&&copy.Workspace.ManualHeight==old.Workspace.ManualHeight&&copy.Workspace.Height==old.Workspace.Height&&copy.AutoStartTools==old.AutoStartTools,"Migration/reset lost existing preferences");}});
    }
    internal static async Task Ui(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
    {
        await test("Integrated module defaults decline confirm disk failure and active stubs",async()=>{var saved=shell.Settings.Copy();Window? manager=null;try{var next=saved.Copy();next.Language="ru";next.Theme="dark";next.Backdrop="solid";next.Workspace.Primary="dns";next.Workspace.Order=new[]{"dns","tg","zapret"};next.Workspace.Visible=new[]{"dns","tg"};next.StartupZapret=false;next.StartupTg=false;shell.ApplySettings(next);await shell.StartSelected(new[]{"zapret","tg"});shell.Workspace.OpenManager();manager=Manager(shell);int launches=shell.Runtime.LaunchCount;string before=File.ReadAllText(files.SettingsPath);shell.Workspace.ConfirmationForTests=_=>false;Click(manager,"ModulesDefaults");Check(File.ReadAllText(files.SettingsPath)==before,"Declined reset wrote settings");shell.Workspace.ConfirmationForTests=_=>true;using(var locked=new FileStream(files.SettingsPath,FileMode.Open,FileAccess.Read,FileShare.None)){Click(manager,"ModulesDefaults");Check(((TextBlock)manager.FindName("ModulesError")).Text.Length>0,"Disk error hidden");}Check(File.ReadAllText(files.SettingsPath)==before&&shell.Settings.StartupZapret==false,"Failed reset claimed persisted defaults");Click(manager,"ModulesDefaults");Check(shell.Settings.Workspace.Order.SequenceEqual(WorkspaceSettings.Modules)&&shell.Settings.Workspace.Visible.SequenceEqual(WorkspaceSettings.Modules)&&shell.Settings.StartupZapret==true&&shell.Settings.StartupTg==true&&shell.Settings.Workspace.Primary=="dns","Reset changed wrong settings");await shell.Refresh();Check(shell.Runtime.LaunchCount==launches&&shell.Observations.All(o=>o.State==ObservedState.Running),"Reset stopped or relaunched tools");Check(!LocalizedTree.Walk(manager).OfType<Button>().Any(b=>b.Name.Contains("Additional")),"Modules additional survived");manager.UpdateLayout();TestsR2.Capture((FrameworkElement)manager.Content,Path.Combine(files.Data,"integrated-defaults-confirmed.png"));manager.Close();manager=null;shell.Workspace.OpenManager();manager=Manager(shell);Check(shell.Workspace.OrderEditor!.Order.SequenceEqual(WorkspaceSettings.Modules),"Reopening lost defaults");}finally{manager?.Close();shell.Workspace.ConfirmationForTests=null;await shell.StopSelected(true);shell.ApplySettings(saved);}});
        await test("Integrated inline drag saves on release cancels and keeps toggle identity",async()=>{var saved=shell.Settings.Copy();Window? manager=null;try{shell.Workspace.OpenManager();manager=Manager(shell);manager.UpdateLayout();var editor=shell.Workspace.OrderEditor!;var toggle=(CheckBox)manager.FindName("Visibledns");string[] initial=editor.Order;editor.DragForTests("zapret",145,true);Check(editor.Order.SequenceEqual(initial)&&files.Load().Workspace.Order.SequenceEqual(initial),"Cancelled drag persisted");editor.DragForTests("zapret",145);Check(editor.Order.Last()=="zapret"&&files.Load().Workspace.Order.SequenceEqual(editor.Order)&&ReferenceEquals(toggle,manager.FindName("Visibledns")),"Released row failed to persist with its controls");manager.UpdateLayout();await Task.Delay(180);TestsR2.Capture((FrameworkElement)manager.Content,Path.Combine(files.Data,"integrated-modules-reordered.png"));manager.Close();manager=null;shell.Workspace.OpenManager();manager=Manager(shell);Check(shell.Workspace.OrderEditor!.Order.Last()=="zapret","Restart/reopen order lost");}finally{manager?.Close();shell.ApplySettings(saved);}});
        await test("Integrated DNS Done never applies or restores an encrypted managed original",async()=>{var saved=shell.Settings.Copy();var isolated=new AppFiles(Path.Combine(files.Root,"test-results/integrated-done-"+Guid.NewGuid().ToString("N")));var fake=TestsDns.Fixture(isolated.Data);fake.State=fake.State.With(DnsFamily.IPv4,fake.State.IPv4 with{Encryption=fake.State.IPv4.Servers.Select(ip=>new DnsDohSettings(ip,"https://xbox-dns.ru/dns-query",2)).ToArray()});var original=fake.State;DnsManagerView.ReaderForTests=fake;DnsManagerView? view=null;try{view=new DnsManagerView(shell,isolated);view.ConfirmationForTests=_=>true;view.SelectProfile("comss");view.Window.Show();int writes=fake.Writes;Click(view.Window,"DnsDone");Check(fake.Writes==writes&&fake.State.SameConfiguration(original),"Done applied DNS");view=new DnsManagerView(shell,isolated);view.ConfirmationForTests=_=>true;view.SelectProfile("comss");view.Window.Show();await view.Power(false);Check(view.Applied,"Mock encrypted application failed");var store=new DnsFileJournalStore(Path.Combine(isolated.Data,"Dns/IsolatedRecovery"),"safe-test");var journal=store.Load(original.AdapterId)!;writes=fake.Writes;view.SelectProfile("magic");Click(view.Window,"DnsDone");Check(fake.Writes==writes&&store.Load(original.AdapterId)!.Id==journal.Id&&store.Load(original.AdapterId)!.Before.SameConfiguration(original),"Done restored, applied pending, or changed original");view=new DnsManagerView(shell,isolated);view.ConfirmationForTests=_=>true;view.Window.Show();await view.Power(true);Check(fake.State.SameConfiguration(original),"Encrypted original not restored after reopening");}finally{if(view!=null){view.ConfirmationForTests=_=>true;view.Window.Close();}DnsManagerView.ReaderForTests=null;shell.ApplySettings(saved);}});
        await test("Integrated module Save stages strategy without replacing running identity",async()=>{var saved=shell.Settings.Copy();Window? window=null;try{string path=Path.Combine(files.Modules,"owned-listing-only");Directory.CreateDirectory(path);foreach(string name in new[]{"general (ALT13).bat","general (ALT2).bat"})File.WriteAllText(Path.Combine(path,name),"listing fixture only; never executed");var next=saved.Copy();next.ZapretDirectory=path;next.Strategy="general (ALT13).bat";next.PendingStrategy="";shell.ApplySettings(next);await shell.StartSelected(new[]{"zapret"});shell.Settings.PendingStrategy="general.bat";files.Save(shell.Settings);string actual=shell.Runtime.ActiveZapretProfile;int launches=shell.Runtime.LaunchCount;window=shell.OpenModuleSettings("zapret");((ComboBox)window.FindName("Strategy")).SelectedItem="general (ALT2).bat";Click(window,"SaveModuleSettings");Check(!window.IsVisible&&shell.Settings.PendingStrategy=="general (ALT2).bat"&&shell.Runtime.ActiveZapretProfile==actual&&shell.Runtime.LaunchCount==launches,"Save changed running strategy or left stale pending choice");}finally{window?.Close();await shell.StopSelected(true);shell.ApplySettings(saved);}});
        await test("Integrated five windows share pinned actions and collapsed advanced sections",async()=>{var saved=shell.Settings.Copy();try{foreach(string language in new[]{"ru","en"})foreach(string theme in new[]{"dark","light"}){var next=saved.Copy();next.Language=language;next.Theme=theme;next.Backdrop="solid";shell.ApplySettings(next);var settings=shell.OpenSettings();var zapret=shell.OpenModuleSettings("zapret");var tg=shell.OpenModuleSettings("tg");var dns=shell.OpenDnsSettings();shell.Workspace.OpenManager();var modules=Manager(shell);try{foreach(var item in new[]{(settings,"SaveSettings","SettingsAdditional","settings"),(zapret,"SaveModuleSettings","ModuleAdditional","zapret"),(tg,"SaveModuleSettings","ModuleAdditional","tg"),(dns,"DnsDone","DnsAdditional","dns"),(modules,"ModulesDone","","modules")}){var window=item.Item1;window.UpdateLayout();var done=(Button)window.FindName(item.Item2);Check(done.ActualHeight==36&&done.ActualWidth>=136,"Footer sizes differ");TestsR2.Capture((FrameworkElement)window.Content,Path.Combine(files.Data,$"integrated-{item.Item4}-{language}-{theme}.png"));if(item.Item3!=""){Click(window,item.Item3);window.UpdateLayout();TestsR2.Capture((FrameworkElement)window.Content,Path.Combine(files.Data,$"integrated-{item.Item4}-expanded-{language}-{theme}.png"));}double height=window.Height;window.Height=360;window.UpdateLayout();Check(done.TranslatePoint(new Point(0,done.ActualHeight),window).Y<=window.ActualHeight,"Pinned action escaped viewport");window.Height=height;window.UpdateLayout();}await Task.Delay(30);}finally{modules.Close();dns.Close();tg.Close();zapret.Close();settings.Close();}}}finally{shell.ApplySettings(saved);}});
    }
}
#endif
